# Involute sampling and the tooth section, translated from the gallery model's Go source.
# Do not edit.
_Point = collections.namedtuple('Point', ['x', 'y'])

_Dimensions = collections.namedtuple('Dimensions', ['pitch', 'base', 'root', 'tip', 'fillet'])

class _ToothPoints:
    def __init__(self, right=None, left=None, rightRoot=None, leftRoot=None, rightRootXY=None, leftRootXY=None):
        self.right = [] if right is None else right
        self.left = [] if left is None else left
        self.rightRoot = rightRoot
        self.leftRoot = leftRoot
        self.rightRootXY = rightRootXY
        self.leftRootXY = leftRootXY

