def _validate(p):
    if p.Module <= 0:
        raise RuntimeError("spurgear: module %g must be positive" % (p.Module,))
    if p.Thickness <= 0:
        raise RuntimeError("spurgear: thickness %g must be positive" % (p.Thickness,))
    if p.Teeth < 3:
        raise RuntimeError("spurgear: teeth %d must be at least 3" % (p.Teeth,))
    if p.Samples < 3:
        raise RuntimeError("spurgear: samples %d must be at least 3" % (p.Samples,))
    if (p.PressureAngle <= 0) or (p.PressureAngle >= (math.pi / 2)):
        raise RuntimeError("spurgear: pressure angle %g must be in (0, pi/2)" % (p.PressureAngle,))
    if p.BoreDiameter < 0:
        raise RuntimeError("spurgear: bore diameter %g must not be negative" % (p.BoreDiameter,))
    if p.CapChamfer < 0:
        raise RuntimeError("spurgear: cap chamfer %g must not be negative" % (p.CapChamfer,))
    if (p.Placement is not None) and not p.Placement.is_valid():
        raise RuntimeError("spurgear: invalid placement frame")
    d = _fx.derive(p)
    if d.root <= 0:
        raise RuntimeError("spurgear: root radius %g must be positive" % (d.root,))
    if d.base <= 0:
        raise RuntimeError("spurgear: base radius %g must be positive" % (d.base,))
    if d.tip <= d.base:
        raise RuntimeError("spurgear: tip radius %g must exceed base radius %g" % (d.tip, d.base,))
    if p.BoreDiameter >= (2 * d.root):
        raise RuntimeError("spurgear: bore diameter %g must be below root diameter %g" % (p.BoreDiameter, 2 * d.root,))
    if math.isnan(d.fillet) or math.isinf(d.fillet):
        raise RuntimeError("spurgear: root fillet radius %g is not finite" % (d.fillet,))
    return

def _rotate(x, y, theta):
    s, c = math.sin(theta), math.cos(theta)
    return _Point((x * c) - (y * s), (x * s) + (y * c))

def _involute_point(base, r):
    ratio = base / r
    if ratio > 1:
        ratio = 1
    t = math.tan(math.acos(ratio))
    s, c = math.sin(t), math.cos(t)
    return _Point(base * (c + (t * s)), -(base * (s - (t * c))))

def _flank_beta(pitch, base, teeth):
    pp = _involute_point(base, pitch)
    return (math.pi / (2 * teeth)) - math.atan2(pp.y, pp.x)

def _sample_flanks(pitch, base, start, tip, teeth, samples, angle):
    left = []
    right = []
    beta = _flank_beta(pitch, base, teeth)
    left = [None] * (samples)
    right = [None] * (samples)
    for i in range(0, samples):
        r = start + (((tip - start) * float(i)) / float(samples - 1))
        m = _involute_point(base, r)
        l = _rotate(m.x, m.y, beta)
        rt = _Point(l.x, -l.y)
        left[i] = _rotate(l.x, l.y, angle)
        right[i] = _rotate(rt.x, rt.y, angle)
    return left, right

def involute_flanks(pitch, base, tip, effectiveTeeth, samples, angle):
    for v in [pitch, base, tip, effectiveTeeth, angle]:
        if math.isnan(v) or math.isinf(v):
            raise RuntimeError("involute flanks: nonfinite scalar input")
    if base <= 0:
        raise RuntimeError("involute flanks: base radius %g must be positive" % (base,))
    elif pitch <= base:
        raise RuntimeError("involute flanks: pitch radius %g must exceed base radius %g" % (pitch, base,))
    elif tip <= pitch:
        raise RuntimeError("involute flanks: tip radius %g must exceed pitch radius %g" % (tip, pitch,))
    elif effectiveTeeth <= 0:
        raise RuntimeError("involute flanks: effective teeth %g must be positive" % (effectiveTeeth,))
    elif samples < 3:
        raise RuntimeError("involute flanks: samples %d must be at least 3" % (samples,))
    l, r = _sample_flanks(pitch, base, base, tip, effectiveTeeth, samples, angle)
    left = [None] * (len(l))
    right = [None] * (len(r))
    for i in range(len(l)):
        left[i] = [l[i].x, l[i].y]
        right[i] = [r[i].x, r[i].y]
    return left, right

def _root_contact(base, d):
    return _Point((base.x * d.root) / d.base, (base.y * d.root) / d.base)

def _tooth_angle(p, k):
    return ((2 * math.pi) * float(k)) / float(p.Teeth)

def _add_tooth_points(s, p, d, angle):
    left, right = _sample_flanks(d.pitch, d.base, d.base, d.tip, float(p.Teeth), p.Samples, angle)
    tp = _ToothPoints()
    tp.right = [None] * (len(right))
    tp.left = [None] * (len(left))
    for i, q in enumerate(right):
        tp.right[i] = s.dimension_point(q.x, q.y)
    for i, q in enumerate(left):
        if i == (len(left) - 1):
            tp.left[i] = s.dimension_arc_end(q.x, q.y)
        else:
            tp.left[i] = s.dimension_point(q.x, q.y)
    tp.leftRootXY = _root_contact(left[0], d)
    tp.rightRootXY = _root_contact(right[0], d)
    tp.leftRoot = s.dimension_arc_end(tp.leftRootXY.x, tp.leftRootXY.y)
    tp.rightRoot = s.dimension_point(tp.rightRootXY.x, tp.rightRootXY.y)
    return tp

def _to_world(f, xy):
    return f.origin().add(f.u().scale(xy.x)).add(f.v().scale(xy.y))

def _shifted(f, dist):
    return _fx.r3_new_frame(f.origin().add(f.n().scale(dist)), f.u(), f.v())

def _placement(p):
    if p.Placement is not None:
        return p.Placement
    return _fx.r3_new_frame(_fx.r3_new_vec(0, 0, 0), _fx.r3_new_vec(1, 0, 0), _fx.r3_new_vec(0, 1, 0))

def _single_profile(s, stage):
    profiles = s.profiles()
    if (len(profiles) != 1) or not profiles[0].Valid:
        raise RuntimeError("%s: want 1 valid profile, got %d" % (stage, len(profiles),))
    return profiles[0]

def _solve_and_verify(s, stage):
    s.solve()
    _fx.sketchcheck_verify_fully_constrained(s)
    return

def _half_angle(d, teeth, r):
    beta = _flank_beta(d.pitch, d.base, teeth)
    m = _involute_point(d.base, r)
    l = _rotate(m.x, m.y, beta)
    return math.atan2(l.y, l.x)

def _closing_radius(d, teeth):
    n = float(teeth)
    limit = math.pi / n
    if _half_angle(d, n, d.base) < limit:
        return d.base
    if _half_angle(d, n, d.root) >= limit:
        raise RuntimeError("no closing radius: adjacent flanks still overlap at the root circle (radius %g)" % (d.root,))
    lo, hi = d.base, d.root
    for i in range(0, 200):
        mid = (lo + hi) / 2
        if _half_angle(d, n, mid) >= limit:
            lo = mid
        else:
            hi = mid
    rq = (lo + hi) / 2
    return (rq + d.root) / 2

def _build_tooth_section(world, plane, p, d, angle):
    s = world.create_sketch(plane, name="Tooth Profile")
    center = s.origin()
    tp = _add_tooth_points(s, p, d, angle)
    last = p.Samples - 1
    s.create_line(tp.rightRoot, tp.right[0])
    s.create_fit_spline(*tp.right)
    s.create_arc(center, tp.right[last], tp.left[last])
    s.create_fit_spline(*tp.left)
    s.create_line(tp.left[0], tp.leftRoot)
    s.create_arc(center, tp.rightRoot, tp.leftRoot)
    _solve_and_verify(s, "tooth section")
    profiles = s.profiles()
    if (len(profiles) != 1) or not profiles[0].Valid:
        raise RuntimeError("tooth section: want 1 valid profile, got %d" % (len(profiles),))
    n = len(profiles[0].Outer)
    if n != 6:
        raise RuntimeError("tooth section: got %d outer curves, want 6" % (n,))
    return s, profiles[0]

def build_tooth_section(world, plane, p, angle):
    if world is None:
        raise RuntimeError("tooth section: nil world")
    if plane is None:
        raise RuntimeError("tooth section: nil plane")
    _validate(p)
    if math.isnan(angle) or math.isinf(angle):
        raise RuntimeError("tooth section: nonfinite angle %g" % (angle,))
    d = _fx.derive(p)
    if d.base < d.root:
        raise RuntimeError("tooth section: embedded flanks are not supported (base radius %g < root radius %g)" % (d.base, d.root,))
    return _build_tooth_section(world, plane, p, d, angle)

def _build_embedded_tooth(world, plane, p, d):
    rc = _closing_radius(d, p.Teeth)
    s = world.create_sketch(plane, name="Tooth Profile")
    center = s.origin()
    left, right = _sample_flanks(d.pitch, d.base, rc, d.tip, float(p.Teeth), p.Samples, 0)
    last = p.Samples - 1
    rp = [None] * (len(right))
    lp = [None] * (len(left))
    for i, q in enumerate(right):
        rp[i] = s.dimension_point(q.x, q.y)
    for i, q in enumerate(left):
        if (i == 0) or (i == last):
            lp[i] = s.dimension_arc_end(q.x, q.y)
        else:
            lp[i] = s.dimension_point(q.x, q.y)
    s.create_fit_spline(*rp)
    s.create_arc(center, rp[last], lp[last])
    s.create_fit_spline(*lp)
    s.create_arc(center, rp[0], lp[0])
    _solve_and_verify(s, "embedded tooth")
    prof = _single_profile(s, "embedded tooth")
    n = len(prof.Outer)
    if n != 4:
        raise RuntimeError("embedded tooth: got %d outer curves, want 4" % (n,))
    return s, prof

def tooth_input_shifted(in_, dist):
    return _shifted(in_.Frame, dist.base())

def tooth_input_plane_at(in_, dist):
    f = tooth_input_shifted(in_, dist)
    return in_.World.create_plane_from_frame(f, name="Twisted Section Plane")

def _variant_tooth(v, r):
    if v.Tooth is not None:
        tooth = v.Tooth(_ToothInput(Doc=r.doc, World=r.world, Params=r.p, Frame=r.frame, Lower=r.lower))
        return tooth
    ts = None
    prof = None
    err = None
    if r.d.base < r.d.root:
        ts, prof = _build_embedded_tooth(r.world, r.lower, r.p, r.d)
    else:
        ts, prof = _build_tooth_section(r.world, r.lower, r.p, r.d, 0)
    tooth = _fx.decad_extrude(r.doc, ts, prof, r.extent, name="Tooth Extrude", body="Tooth")
    return tooth

def _fillet_spur_roots(doc, body, r, embedded):
    radius = doc.param("fillet_radius")
    if embedded:
        return _fillet_embedded(body, r.frame, r.teeth, radius)
    roots = []
    left, right = _sample_flanks(r.d.pitch, r.d.base, r.d.base, r.d.tip, float(r.teeth), r.p.Samples, 0)
    for k in range(0, r.teeth):
        a = _tooth_angle(r.p, k)
        rr = _root_contact(right[0], r.d)
        lr = _root_contact(left[0], r.d)
        roots = roots + [_rotate(rr.x, rr.y, a), _rotate(lr.x, lr.y, a)]
    return _fillet_roots_value(body, r.frame, roots, radius)

def _fillet_roots_value(body, frame, roots, radius):
    axis = frame.n()
    edges = _fx.decad_edges(_fx.decad_parallel_to(axis)).select_edges(body)
    corners = []
    for e in edges:
        start = e.start().position().Value
        for root in roots:
            if start.sub(_to_world(frame, root)).len() <= 1e-6:
                corners = corners + [start]
                break
    if len(corners) != len(roots):
        raise RuntimeError("spurgear: matched %d root edges, want %d" % (len(corners), len(roots),))
    sel = _fx.decad_edges(_fx.decad_parallel_to(axis), _fx.decad_endpoint_at(corners[0]))
    for c in corners[1:]:
        sel = sel.or_(_fx.decad_parallel_to(axis), _fx.decad_endpoint_at(c))
    out = _fx.decad_fillet(body, sel.exactly(len(corners)), radius, name="Root Fillet")
    return out

def _fillet_embedded(body, frame, teeth, radius):
    sel = _fx.decad_edges(_fx.decad_parallel_to(frame.n()), _fx.decad_concave()).exactly(2 * teeth)
    out = _fx.decad_fillet(body, sel, radius, name="Root Fillet")
    return out

def _build_bore_profile(world, p, margin):
    frame = _placement(p)
    low = _shifted(frame, -margin)
    plane = world.create_plane_from_frame(low, name="Bore Tool Plane")
    s = world.create_sketch(plane, name="Bore Profile")
    circle = s.create_circle(s.origin(), p.BoreDiameter / 2)
    diameter = _fx.sketch_new_diameter(circle, p.BoreDiameter)
    s.add_constraint(diameter)
    s.bind(diameter, world.params(), "bore_diameter")
    _solve_and_verify(s, "bore tool")
    prof = _single_profile(s, "bore tool")
    return s, prof

def _cut_bore(doc, gear, p):
    marginValue = doc.param("tool_margin")
    length = doc.param("bore_tool_length")
    world = _fx.sketch_new_world()
    s, prof = _build_bore_profile(world, p, marginValue.base())
    tool = _fx.decad_extrude(doc, s, prof, _fx.decad_distance(D=length, Dir=_fx.DECAD_ALONG), name="Bore Tool Extrude", body="Bore Tool")
    out = _fx.decad_cut(gear, tool, name="Bore Cut")
    return out

def _chamfer_outer_caps(gear, setback):
    sel = _fx.decad_edges(_fx.decad_outer_loop_of(_fx.decad_cap_start(gear))).or_(_fx.decad_outer_loop_of(_fx.decad_cap_end(gear)))
    out = _fx.decad_chamfer(gear, sel, setback, name="Cap Chamfer")
    return out

def _variant_assemble(v, r):
    doc, p = r.doc, r.p
    d, frame, lower, extent = r.d, r.frame, r.lower, r.extent
    world, teeth = r.world, r.teeth
    embedded = d.base < d.root
    tooth = _variant_tooth(v, r)
    ds = world.create_sketch(lower, name="Root Disc Profile")
    circle = ds.create_circle(ds.origin(), d.root)
    radius = _fx.sketch_new_radius(circle, d.root)
    ds.add_constraint(radius)
    ds.bind(radius, world.params(), "root_radius")
    _solve_and_verify(ds, "spurgear: root disc")
    dp = _single_profile(ds, "spurgear: root disc")
    disc = _fx.decad_extrude(doc, ds, dp, extent, name="Root Disc Extrude", body="Gear Body")
    copies = _fx.decad_pattern_copies(tooth, _fx.decad_circular_pattern(Center=frame.origin(), Axis=frame.n(), Count=teeth), name="Tooth Pattern")
    body = _fx.decad_union(disc, *[tooth] + list(copies), name="Teeth Join")
    if not body.is_solid():
        raise RuntimeError("spurgear: joined gear is not a solid")
    if v.RootFillet is not None:
        body = v.RootFillet(doc, body, frame)
    elif d.fillet > 0:
        body = _fillet_spur_roots(doc, body, r, embedded)
    if p.BoreDiameter > 0:
        body = _cut_bore(doc, body, p)
    if p.CapChamfer > 0:
        setback = doc.param("cap_chamfer")
        body = _chamfer_outer_caps(body, setback)
    return body


